import{_ as o,l as n,o as e,c as i,v as t,p as s,x as l,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"SABR 模型","description":"","frontmatter":{"title":"SABR 模型","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sabr.md","filePath":"quant/sabr.md","lastUpdated":1789023840000}'),B={name:"quant/sabr.md"};function A(c,a,m,u,E,b){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="sabr-模型" tabindex="-1">SABR 模型 <a class="header-anchor" href="#sabr-模型" aria-label="Permalink to &quot;SABR 模型&quot;">​</a></h1><div class="epigraph"><p>用随机波动率乘在远期的 CEV 扩散上，再对 Black 隐含波动率做奇异摄动，得到的显式近似足以管理微笑风险，而不必每次都解二维 PDE。</p><footer>—— Hagan, Kumar, Lesniewski and Woodward, Managing Smile Risk, Wilmott, 2002</footer></div><p>利率与外汇的经纪商报价不是随机波动率的五个参数，而是每个到期的一条隐含波动率微笑，再加对冲用的 Delta 与 Vega。Patrick Hagan、Deep Kumar、Andrew Lesniewski 与 Diana Woodward 在 2002 年 <em>Wilmott</em> 的「Managing Smile Risk」里提出 SABR（Stochastic Alpha Beta Rho）：远期服从常弹性方差（CEV），瞬时波动率本身再做几何布朗运动，二者相关。模型的关键交付不是转移密度的傅里叶公式，而是一套对 Black（或 Bachelier）隐含波动率的渐近展开，使交易员能用 \\(\\alpha,\\beta,\\rho,\\nu\\) 直接标记微笑，并一致地计算对冲比。它与 <a href="/quant/heston">Heston</a> 同属随机波动，但 SABR 针对的是「给定到期、盯住远期」的微笑管理，而不是股票香草的全局曲面闭合定价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每条微笑用独立的三次样条去插值，相邻执行价的对冲比会跳，日历价差与蝶式的无套利难以监控，参数也没有动力学含义。局部波动率能拟合一条微笑，但 Hagan 等人强调：局部波动率对冲时，微笑会朝与市场相反的方向移动——现货上涨，模型里的微笑往下掉，而市场往往一起上移。随机波动率可以纠正这种动态。需要的是尽量少的参数、对每个到期单独校准、以及不必数值求解就能从参数读出 Black 波动率。</p><p>CEV 已经能用 \\(\\beta\\) 在对数正态（\\(\\beta=1\\)）与正态（\\(\\beta=0\\)）之间选择杠杆；再让瞬时波动 \\(\\sigma_t\\)（常记为 \\(\\alpha\\) 的过程）随机，并用 \\(\\rho\\) 产生偏斜、\\(\\nu\\) 产生弯曲，一条到期的微笑就有了交易语言。问题收成：在小波动、不太长的到期下，隐含波动率对状态的展开是否足够准，准到可以当报价公式用。</p><h3 id="远期而不是现货" tabindex="-1">远期而不是现货 <a class="header-anchor" href="#远期而不是现货" aria-label="Permalink to &quot;远期而不是现货&quot;">​</a></h3><p>SABR 写在远期 \\(F_t\\) 上。对给定到期 \\(T\\) 的欧式，远期在定价测度下是鞅（忽略凸性调整与多曲线细节时），漂移为零，只剩扩散。这与利率上限、互换期权、外汇 RR/BF 的市场惯例一致：报价的是该到期的微笑，标的是对应远期。股票指数期权有时也按远期 SABR 来标记单到期，但跨到期必须另做期限结构，不能假设同一个 \\(\\alpha\\) 过程服务所有 \\(T\\)——原文的摄动是对固定 \\(T\\) 的。</p><p><span class="marginnote">\\(\\alpha\\) 是今日的瞬时波动水平，不是 Black 隐含波动本身。ATM 附近二者接近，翼部由 \\(\\beta,\\rho,\\nu\\) 推开。把经纪商 ATM vol 直接当成 \\(\\alpha\\) 而不做 Hagan 公式反演，是常见的数量级错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>远期与瞬时波动满足</p> \\[dF_t = \\sigma_t F_t^\\beta\\,dW_t, \\qquad d\\sigma_t = \\nu\\sigma_t\\,dZ_t, \\qquad dW\\,dZ=\\rho\\,dt, \\]<p>今日 \\(\\sigma_0=\\alpha\\)，\\(F_0\\) 为对应远期。\\(\\beta\\in[0,1]\\) 常被冻结：利率上 \\(\\beta=0.5\\) 一类选择很常见，外汇上 \\(\\beta=1\\) 更接近对数正态。Hagan 等人用奇异摄动得到 Black 隐含波动率 \\(\\sigma_{\\mathrm{B}}(K)\\) 的近似，领头项在 ATM 为</p> \\[\\sigma_{\\mathrm{B}}(F) \\approx \\frac{\\alpha}{F^{1-\\beta}}\\left(1+\\left(\\frac{(1-\\beta)^2}{24}\\frac{\\alpha^2}{F^{2-2\\beta}}+\\frac{\\rho\\beta\\nu\\alpha}{4F^{1-\\beta}}+\\frac{2-3\\rho^2}{24}\\nu^2\\right)T+\\cdots\\right), \\]<p>对 \\(K\\neq F\\) 还有 \\(z/\\chi(z)\\) 一类因子，其中 \\(z\\) 正比于 \\(\\nu\\alpha^{-1}\\ln(F/K)\\) 的 CEV 修正。正常模型（Bachelier）报价有平行的展开。交易员用这套公式从市场微笑解 \\(\\alpha,\\rho,\\nu\\)（\\(\\beta\\) 给定），再对任意 \\(K\\) 插值、外推。</p><h3 id="参数与微笑形状" tabindex="-1">参数与微笑形状 <a class="header-anchor" href="#参数与微笑形状" aria-label="Permalink to &quot;参数与微笑形状&quot;">​</a></h3><p>\\(\\alpha\\) 上下平移水平；\\(\\beta\\) 同时影响 ATM 杠杆与偏斜，与 \\(\\rho\\) 共线，故常固定 \\(\\beta\\) 只放 \\(\\rho\\)；\\(\\rho\\) 管偏斜方向；\\(\\nu\\)（vol-of-vol）管翼部弯曲。负 \\(\\rho\\) 让低执行价波动更高。到期 \\(T\\) 进入展开的高阶项，因此同一套 \\((\\alpha,\\rho,\\nu)\\) 不能自动服务另一个到期：每个期权到期通常单独校准，再把参数沿期限光滑，这是「SABR 曲面」的拼法，不是单一二维扩散的全局解。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Hagan 公式的吸引力在于：对冲比可以对近似公式求解析导数，而不必对 PDE 做伴随。Delta 是否包含微笑随现货的移动（sticky strike / sticky delta / SABR 预测的 sticky 行为）会导致不同的对冲量。原文的论点正是：用与模型一致的动态去算 Delta，才能「管理微笑风险」，而不是把微笑当静态带子。SABR 预测的是：波动的随机部分让微笑有随远期平移的成分，CEV 杠杆又让水平依赖 \\(F^{\\beta-1}\\)。</p><p>摄动是渐近，不是恒等式。极端翼部、很长到期、很大的 \\(\\nu\\)，近似会变负或非单调，必须切翼、改用更好的展开（后来的 Hagan 高阶、Obloj、Paulot 等）或改回数值求解。负概率、无套利破坏出现在近似层，不一定出现在原始 SDE 里——原始 SABR 在 \\(\\beta\\lt 1\\) 时也能到达零，吸收性质另当别论。把市场翼部的无套利责任全部推给 2002 年领头项公式，是误用。</p><h3 id="与-heston-的使用场景差异" tabindex="-1">与 Heston 的使用场景差异 <a class="header-anchor" href="#与-heston-的使用场景差异" aria-label="Permalink to &quot;与 Heston 的使用场景差异&quot;">​</a></h3><p>Heston 有仿射特征函数，适合股票香草曲面、方差相关产品、需要特征函数校准的场景。SABR 几乎没有好用的特征函数闭合（一般 \\(\\beta\\)），却有交易员要的隐含波动率显式近似，适合利率/外汇按到期标记。二者都有相关与 vol-of-vol，但 SABR 的 \\(\\beta\\) 把局部杠杆从相关里拆出一截。不要用 Heston 的 \\(\\sigma\\) 去对 SABR 的 \\(\\nu\\) 做无换算比较，也不要把 SABR 单到期参数解释成能给奇异路径产品唯一价格——那需要指定完整的动态与测度，单到期微笑不够。</p><p><span class="marginnote">固定 \\(\\beta\\) 再校准 \\(\\rho\\)，是识别策略，不是说 \\(\\beta\\) 在经济上不重要。\\(\\beta\\) 改变对冲的现货杠杆：\\(\\beta=0\\) 更接近正态点差，\\(\\beta=1\\) 更接近对数百分比。互换期权与上限的 Delta 惯例不同，要把报价惯例与 \\(\\beta\\) 一起声明。</span></p>',23)),(e(),s(d,null,{default:l(()=>[p(r,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E8%BF%9C%E6%9C%9F%20F%22%5D%20--%3E%20CEV%5B%22CEV%20%E6%89%A9%E6%95%A3%20F%5E%CE%B2%22%5D%0A%20%20A%5B%22%E7%9E%AC%E6%97%B6%E6%B3%A2%E5%8A%A8%20%CE%B1%22%5D%20--%3E%20CEV%0A%20%20Nu%5B%22%CE%BD%20%E4%B8%8E%20%CF%81%22%5D%20--%3E%20A%0A%20%20CEV%20--%3E%20Smile%5B%22%E5%B8%82%E5%9C%BA%E5%BE%AE%E7%AC%91%22%5D%0A%20%20A%20--%3E%20Hagan%5B%22Hagan%20%E9%9A%90%E5%90%AB%E6%B3%A2%E5%8A%A8%E8%BF%91%E4%BC%BC%22%5D%0A%20%20Hagan%20--%3E%20Smile%0A%20%20Smile%20--%3E%20Hedge%5B%22%E4%B8%8E%E5%BE%AE%E7%AC%91%E4%B8%80%E8%87%B4%E7%9A%84%20Delta%20%2F%20Vega%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>原文针对单一远期、单一到期的欧式。互换期权的底层是互换利率，上限是 LIBOR/期限利率，折现与投影在 <a href="/quant/multi-curve-ois">多曲线</a> 下不是同一条；SABR 仍可标记投影远期的微笑，但定价要用正确的折现。CMS、障碍、美式提前行权超出领头项公式的担保范围。2008 年后负利率使对数正态 SABR 不适，市场改用移位 SABR 或正态 SABR，这是对原公式的扩展，应单独引用后续文献。</p><p>校准若放任 \\(\\nu\\) 极大去拟合远翼，ATM 的时间衰减与对冲会坏掉。翼部应用无套利密度检查：隐含密度为负说明近似或外推失败。Hagan 等人（2002）贡献的是微笑参数化与对冲哲学，加上一套广泛使用的摄动公式；它不是全局随机波动率的估计程序，也不是波动率曲面的无套利定理。</p><p><span class="marginnote">Wilmott 杂志论文不是期刊定理。公式被全市场采用，是因为它在报价速度与可微性上赢了；精度边界要靠后续数值与高阶展开来补，不能靠引用次数自动成立。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SABR（Hagan et al., 2002）在远期 CEV 上叠加对数正态随机波动，用 \\(\\alpha,\\beta,\\rho,\\nu\\) 标记单一到期的微笑。</li><li>交付物是 Black/Bachelier 隐含波动的奇异摄动近似，便于插值与解析对冲，而不是 Heston 式特征函数。</li><li>\\(\\beta\\) 与 \\(\\rho\\) 都影响偏斜，实务常冻结 \\(\\beta\\)；\\(\\nu\\) 管弯曲，\\(\\alpha\\) 管水平。</li><li>近似在远翼与长到期会失效；负利率需移位或正态版本。</li><li>局部波动率的微笑动态与市场常相反，是原文主张随机波动对冲的动机。</li><li>出处：Hagan, Kumar, Lesniewski, Woodward, <em>Wilmott</em>, 2002；随机波动对照见 Heston, <em>RFS</em>, 1993；产品与希腊字母语境见 Hull。</li></ul>',6))])}const g=o(B,[["render",A]]);export{S as __pageData,g as default};
